<script setup>import { router } from '@inertiajs/vue3'; import AdminLayout from '../../../Layouts/AdminLayout.vue'; defineProps({messages:Object}); const read=id=>router.put(`/admin/messages/${id}`); const remove=id=>router.delete(`/admin/messages/${id}`);</script>
<template><AdminLayout><h1 class="font-serif text-4xl">বার্তা</h1><div class="mt-8 space-y-4"><article v-for="message in messages.data" :key="message.id" class="rounded-2xl bg-white p-6" :class="!message.is_read?'ring-2 ring-[#e6b36d]':''"><div class="flex justify-between"><div><b>{{ message.name }}</b><span class="ml-3 text-sm text-[#87938d]">{{ message.email }}</span></div><div class="flex gap-4 text-sm"><button v-if="!message.is_read" @click="read(message.id)" class="text-[#1d6a61]">পঠিত করুন</button><button @click="remove(message.id)" class="text-red-600">মুছুন</button></div></div><p class="mt-4 leading-7 text-[#60716c]">{{ message.message }}</p></article><p v-if="!messages.data?.length" class="rounded-2xl bg-white p-10 text-center text-[#718079]">কোনো বার্তা নেই।</p></div></AdminLayout></template>
